// NOVA Personal GPU Cloud — NOVA Cloud Storage: shared test support
// (not a test file).
//
// Temp storage roots live under test/storage/.tmp/ (inside the repo, on
// the home filesystem) — NOT os.tmpdir(): /tmp is a 512 MB tmpfs and the
// chunked-upload test stores 256 MB. Every temp root is removed in
// t.after(). All test data is synthetic generated bytes — no real media.

import { createHash } from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';
import { Readable } from 'node:stream';
import { fileURLToPath } from 'node:url';
import { createStorage } from '../../src/storage/index.js';

export const GPU_CLOUD_ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..');

export function tempStorageRoot(t) {
  const base = path.join(GPU_CLOUD_ROOT, 'test', 'storage', '.tmp');
  fs.mkdirSync(base, { recursive: true });
  const dir = fs.mkdtempSync(path.join(base, 'store-'));
  t.after(() => fs.rmSync(dir, { recursive: true, force: true }));
  return dir;
}

export function makeStorage(t, opts = {}) {
  return createStorage({ rootDir: tempStorageRoot(t), ...opts });
}

// Controllable clock (same idea as the GPU Manager's tests).
export function fakeClock(start = 1_800_000_000_000) {
  let t = start;
  return {
    now: () => t,
    advance: (ms) => {
      t += ms;
    },
    set: (v) => {
      t = v;
    },
  };
}

export function sleep(ms) {
  return new Promise((r) => setTimeout(r, ms));
}

// Deterministic pseudo-random bytes: each 1 MiB block is filled with a
// repeating 32-byte pattern derived from the block index + seed. Fast to
// generate (Buffer.fill is native), identical every run, and the pattern
// differs per block so a swapped-chunks bug changes the hash.
export function deterministicBlock(index, size, seed = 1) {
  const pattern = createHash('sha256').update(`nova-block-${seed}-${index}`).digest();
  const buf = Buffer.alloc(size);
  buf.fill(pattern);
  return buf;
}

export function deterministicStream(totalBytes, seed = 1) {
  async function* gen() {
    let remaining = totalBytes;
    let i = 0;
    while (remaining > 0) {
      const size = Math.min(1024 * 1024, remaining);
      yield deterministicBlock(i, size, seed);
      remaining -= size;
      i += 1;
    }
  }
  return Readable.from(gen());
}

export async function hashDeterministic(totalBytes, seed = 1) {
  const hash = createHash('sha256');
  for await (const piece of deterministicStream(totalBytes, seed)) {
    hash.update(piece);
  }
  return hash.digest('hex');
}

export async function hashStream(stream) {
  const hash = createHash('sha256');
  for await (const piece of stream) {
    hash.update(piece);
  }
  return hash.digest('hex');
}
